import { Meta, StoryObj } from "@storybook/react";
import { pageLock } from "./page-lock";
import { expect, userEvent, within } from "storybook/test";

import { WithMockedDate, argTypesMockDate, withMockedDate } from "../../../../.storybook/preview";
import labels from "../../../labels/labels";

const LockedPage = pageLock(() => {
  return (
    <div>
      <h1>Secret page!</h1>
      <p>Very hidden content</p>
    </div>
  );
});

const meta = {
  title: "Modules/Page Lock",
  component: LockedPage,
  decorators: [withMockedDate],
  argTypes: argTypesMockDate,
} satisfies Meta<WithMockedDate<typeof LockedPage>>;

export default meta;

//Remove the "{{0}}"" at the end of the label
const trimmedTimeLockParagraphText = labels.sv.dateTimeLockMessageParagraph.substring(
  0,
  labels.sv.dateTimeLockMessageParagraph.length - "{{0}}".length,
);

export const Primary: StoryObj<typeof meta> = {
  args: {
    mockedDate: new Date("2024-08-13T08:11:20.297Z"),
    lockType: "Code",
    lockValue: "hunter2",
    setIsViewportScrollable: () => {
      return;
    },
    lockErrorMsg: "Locked error message",
    lockInputLabel: undefined,
    lockInputPlaceholder: undefined,
  },
};

export const DateTimeLockNotPassed: StoryObj<typeof meta> = {
  play: async ({ canvasElement }) => {
    await new Promise((resolve) => setTimeout(resolve, 2_000));
    const canvas = within(canvasElement);
    expect(canvas.getByText(labels.sv.dateTimeLockMessageHeading)).toBeInTheDocument();
  },
  args: {
    dateTimeLock: "2024-08-01T18:00", //NOTE! This will always be in Europe/Stockholm timezone
    mockedDate: new Date("2024-08-01T17:55:00.000+02:00"), //An exact point in time using +2h offset
  },
};

export const DateTimeLockHasPassed: StoryObj<typeof meta> = {
  play: async ({ canvasElement }) => {
    await new Promise((resolve) => setTimeout(resolve, 2_000));
    const canvas = within(canvasElement);
    expect(canvas.queryByText(labels.sv.dateTimeLockMessageHeading)).toBeNull();
  },
  args: {
    dateTimeLock: "2024-08-01T18:00", //NOTE! This will always be in Europe/Stockholm timezone
    mockedDate: new Date("2024-08-01T18:01:00.000+02:00"), //An exact point in time using +2h offset (Stockholm in summertime)
  },
};

export const CodeLockAndDateTimeLockNotPassed: StoryObj<typeof meta> = {
  play: async ({ canvasElement }) => {
    await new Promise((resolve) => setTimeout(resolve, 2_000));
    const canvas = within(canvasElement);

    expect(canvas.getByText(trimmedTimeLockParagraphText, { exact: false })).toBeInTheDocument();
    expect(canvas.getByPlaceholderText(labels.sv.inputPlaceholderPromoCode)).toBeDisabled();
  },
  args: {
    ...Primary.args,
    ...DateTimeLockNotPassed.args,
  },
};

export const CodeLockAndDateTimeLockHasPassed: StoryObj<typeof meta> = {
  play: async ({ canvasElement }) => {
    await new Promise((resolve) => setTimeout(resolve, 2_000));
    const canvas = within(canvasElement);

    expect(canvas.queryByText(trimmedTimeLockParagraphText, { exact: false })).toBeNull();

    await new Promise((resolve) => setTimeout(resolve, 1000));
    await userEvent.type(canvas.getByPlaceholderText("Skriv in din kampanjkod här"), "hunter2");
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");

    expect(canvas.queryByText(labels.sv.dateTimeLockMessageHeading)).toBeNull();
  },
  args: {
    ...Primary.args,
    ...DateTimeLockHasPassed.args,
  },
};
