export type LockType = "Code" | "Referrer" | "Location Parameters";

const PageLockModal = ({ children }: PropsWithChildren) => {
  return (
    <Modal
      isOpen={true}
      onClose={() => {
        //never want to close the lock modal
      }}
      isClosable={false}
      portalId={MODAL_PORTAL_ID}
      innerClassName={styles.modalInner}
      blurBackground
    >
      {children}
    </Modal>
  );
};

type CodeLockProps<P> = {
  code: string;
  lockInputLabel?: string;
  lockInputPlaceholder?: string;
  lockErrorMsg: string;
  hasPassed: boolean;
  /** Indicates whether the entered code should be cached until 04:00 the following morning, decreasing the number of times the user needs to enter the code */
  cacheCode?: boolean;
  setHasPassed: (passed: boolean) => void;
  setIsViewportScrollable: (passed: boolean) => void;
  isDisabled: boolean;
  bottomText?: string;
  Component: React.ComponentType<{ isLocked: boolean } & P>;
  props: P;
};
const CodeLock = <P,>({
  code,
  lockInputLabel,
  lockInputPlaceholder,
  lockErrorMsg,
  hasPassed,
  cacheCode,
  setHasPassed,
  setIsViewportScrollable,
  isDisabled,
  bottomText,
  Component,
  props,
}: CodeLockProps<P>) => {
  const { t } = useTranslation();
  const initialCodeForm = getInitialForm();
  initialCodeForm.fields.set(
    "code",
    buildField("code", {
      isRequired: true,
      errorText: lockErrorMsg,
      label: lockInputLabel ?? t("promoCode"),
      placeholder: lockInputPlaceholder ?? t("inputPlaceholderPromoCode"),
    }),
  );

  const [codeForm, isCodeFormValid, codeFormOnChange] = useForm(initialCodeForm);

  useEffect(() => {
    setIsViewportScrollable(false);
    window && window.scrollTo(0, 0);

    if (cacheCode && typeof location !== "undefined") {
      const value = LocalStorageHelper.getItem(`pageLock:${JSON.stringify(location.pathname)}`);
      if (code.toUpperCase() === value) {
        setHasPassed(true);
      }
    }

    return () => {
      setIsViewportScrollable(true);
    };
  }, []);

  useEffect(() => {
    if (hasPassed) {
      setIsViewportScrollable(true);
    }
  }, [hasPassed, setIsViewportScrollable]);

  const onInputChange = (value: string) => {
    const valueUpperCase = value.toUpperCase();
    codeFormOnChange("code", valueUpperCase, { instantValidate: true });
  };

  const submitCode = () => {
    const value = codeForm.fields.get("code")?.value ?? "";
    const isValid = code.toUpperCase() === value;

    codeFormOnChange("code", value, { isValid });

    if (isValid) {
      setHasPassed(true);
      if (cacheCode && typeof location !== "undefined") {
        LocalStorageHelper.setItem(
          `pageLock:${JSON.stringify(location.pathname)}`,
          value,
          // 04:00 in the morning the next day
          dayjs().add(1, "day").startOf("day").add(4, "hours").valueOf(),
        );
      }
    }
  };

  const handleKeyDown: KeyboardEventHandler<HTMLInputElement> = (e) => {
    if (e.key === "Enter") {
      submitCode();
    }
  };

  return (
    <div>
      <PageLockModal>
        <div className={styles.content}>
          <InputField
            focus={true}
            className={styles.input}
            formField={codeForm.fields.get("code")}
            onChange={(_fieldName, value) => onInputChange(value)}
            onKeyDown={handleKeyDown}
            isDisabled={isDisabled}
          />
          <PrimaryButton
            className={styles.button}
            isFullWidth={true}
            isDisabled={!isCodeFormValid || isDisabled}
            label={t("activate")}
            onClick={submitCode}
          />
          {bottomText && <p>{bottomText}</p>}
        </div>
      </PageLockModal>
      <Component isLocked={true} {...props} />
    </div>
  );
};

/**
 * Checks that the Referer [sic]-header is valid against validReferrerString.
 *
 * validReferrerString may contain multiple `;`-separated referrers, with protocol optional.
 * See tests for the detailed matching rules (case-sensitivity, spoofing guards, etc).
 */
export const referrerIsValid = (referrerValue: string, validReferrerString: string) => {
  let referrerUrl: URL;
  try {
    // only allow well-formed URL:s as referrer
    referrerUrl = new URL(referrerValue);
  } catch {
    console.warn(`Malformed or invalid referrerValue: "${referrerValue}"`);
    return false;
  }
  return validReferrerString
    .split(";") // should be possible to have multiple valid referrers, split by `;`
    .map((s) => s.trim())
    .filter((s) => !!s) // trim and ignore all empty entries
    .flatMap((maybeProtocol) => {
      // if we have validReferrer-entries without a protocol, allow both http and https
      if (maybeProtocol.startsWith("https://") || maybeProtocol.startsWith("http://")) {
        return [maybeProtocol];
      }
      return [`https://${maybeProtocol}`, `http://${maybeProtocol}`];
    })

    .flatMap((withProtocol) => {
      try {
        // ignore malformed entries (e.g. a typo in the CMS) instead of throwing
        return [new URL(withProtocol)];
      } catch {
        console.error(`Malformed or invalid validReferrerString entry: "${withProtocol}"`);
        return [];
      }
    })
    .some((validReferrerUrl) => {
      return (
        // check origin to prevent domain-suffix spoofing
        referrerUrl.origin === validReferrerUrl.origin &&
        // when domains are correct, make *case-sensitive* prefix-match (origins are automatically lowercased in `new URL`)
        referrerUrl.toString().startsWith(validReferrerUrl.toString())
      );
    });
};

type ReferrerLockProps<P> = {
  validReferrer: string;
  lockErrorMsg: string;
  setHasPassed: (passed: boolean) => void;
  setIsViewportScrollable: (passed: boolean) => void;
  Component: React.ComponentType<{ isLocked: boolean } & P>;
  props: P;
};
const ReferrerLock = <P,>({
  validReferrer,
  lockErrorMsg,
  setHasPassed,
  setIsViewportScrollable,
  Component,
  props,
}: ReferrerLockProps<P>) => {
  useEffect(() => {
    const referrer = document.referrer;
    if (referrer && referrerIsValid(referrer, validReferrer)) {
      setHasPassed(true);
    } else {
      window && window.scrollTo(0, 0);
      setIsViewportScrollable(false);
    }

    return () => {
      setIsViewportScrollable(true);
    };
  }, []);

  return (
    <div>
      <PageLockModal>
        <div className={styles.content}>
          <p className={styles.error}>{lockErrorMsg}</p>
        </div>
      </PageLockModal>
      <Component isLocked={true} {...props} />
    </div>
  );
};

type LocationParametersLock<P> = {
  locationParameters?: string;
  validPromoCode: string;
  lockErrorMsg: string;
  setHasPassed: (passed: boolean) => void;
  setIsViewportScrollable: (passed: boolean) => void;
  Component: React.ComponentType<{ isLocked: boolean } & P>;
  props: P;
};
const LocationParametersLock = <P,>({
  locationParameters = "",
  validPromoCode,
  lockErrorMsg,
  setHasPassed,
  setIsViewportScrollable,
  Component,
  props,
}: LocationParametersLock<P>) => {
  useEffect(() => {
    const parameterPairs = locationParameters.substring(1).split("&");
    const promoParameterPair = parameterPairs.find((parameterPair) => parameterPair.split("=")[0] === "promo");
    const promoCode = promoParameterPair && promoParameterPair.split("=")[1];

    if (promoCode === validPromoCode) {
      setHasPassed(true);
    } else {
      window && window.scrollTo(0, 0);
      setIsViewportScrollable(false);
    }

    return () => {
      setIsViewportScrollable(true);
    };
  }, []);

  return (
    <div>
      <PageLockModal>
        <div className={styles.content}>
          <p className={styles.error}>{lockErrorMsg}</p>
        </div>
      </PageLockModal>
      <Component isLocked={true} {...props} />
    </div>
  );
};

const productHasProductData = (
  p: ProductBlockFragment,
): p is Omit<ProductBlockFragment, "productData"> & {
  productData: NonNullable<ProductBlockFragment["productData"]>;
} => {
  return p.productData !== undefined;
};

const hasValidityTimeToPassed = (validity: ValidityItem | undefined) => {
  if (!validity) {
    return false;
  }
  const timePart = validity.timeTo ? `T${validity.timeTo}` : "T23:59";
  const dateTimeString = `${validity.dateTo}${timePart}`;

  return DateHelper.hasDatePassed(dateTimeString);
};

type MyPageLock<P> = {
  necessaryProducts: Array<ProductBlockFragment>;
  blockingProducts: Array<ProductBlockFragment>;
  ignorePassedBlockingProducts: boolean;
  lockNecessaryProductsRatio?: number;
  lockMyPageMessageNotNecessaryProducts?: TextBlockProps;
  lockMyPageMessageBlockingProducts?: TextBlockProps;
  lockMyPageMessageNotLoggedIn?: TextBlockProps;
  setHasPassed: (passed: boolean) => void;
  Component: React.ComponentType<{ isLocked: boolean } & P>;
  props: P;
};
const MyPageLock = <P,>({
  necessaryProducts,
  blockingProducts,
  ignorePassedBlockingProducts,
  lockNecessaryProductsRatio,
  lockMyPageMessageNotNecessaryProducts,
  lockMyPageMessageBlockingProducts,
  lockMyPageMessageNotLoggedIn,

  auth,
  setHasPassed,
  Component,
  props,
}: MyPageLock<P> & AuthorizeProps) => {
  const { t } = useTranslation();
  const homeRoute = routes.getSitePath();

  const lockState = useMemo(() => {
    if (auth.isFetchingSession || auth.isFetchingProducts || !auth.sessionFetched) {
      return "LOADING" as const;
    }
    if (!auth.isLoggedIn && auth.sessionFetched) {
      return "NOT_LOGGED_IN" as const;
    }
    if (auth.isLoggedIn) {
      const allUsersProducts = [
        ...(auth.products?.webOrders.flatMap((webOrder) =>
          webOrder.rows.map((r) => ({
            productId: r.productId,
            rowId: r.id,
            bonusCodeAllowed: r.allowedActions.bonusCode.isAllowed,
            hasValidityTimeToPassed: hasValidityTimeToPassed(r.validity),
          })),
        ) || []),
        //Here is where accepted gift rows end up. They don't exist in webOrders.rows
        ...(auth.products?.looseRows.map((r) => ({
          productId: r.productId,
          rowId: r.id,
          bonusCodeAllowed: r.allowedActions.bonusCode.isAllowed,
          hasValidityTimeToPassed: hasValidityTimeToPassed(r.validity),
        })) || []),
        //Here is where accepted gift season passes end up. They also don't exist in webOrders.rows
        ...(auth.products?.seasonPasses?.map((s) => ({
          productId: s.productId,
          rowId: s.orderRowId,
          bonusCodeAllowed: s.allowedActions.bonusCode.isAllowed,
          hasValidityTimeToPassed: hasValidityTimeToPassed(s.validity),
        })) || []),
      ];

      //A product row could exist in e.g both webOrders.rows and seasonPasses.
      //We use the rowId to determine uniqueness and only keep one of them, so we don't count it twice.
      const uniqueProducts = new Map(allUsersProducts.map((product) => [product.rowId, product] as const));

      //To be considered for the necessary check, only keep the products that have `bonusCodeAllowed` set to `true`.
      const productIdsUsedForNecessaryChecks = Array.from(uniqueProducts.values())
        .filter((product) => product.bonusCodeAllowed)
        .map((product) => product.productId);

      const productIdsUsedForBlockingChecks = Array.from(uniqueProducts.values())
        .filter((product) => {
          //If we should _ignore passed blocking products_, we filter out products that have a validity time that has passed.
          //They will then not be consired blocking anymore.
          if (ignorePassedBlockingProducts) {
            return !product.hasValidityTimeToPassed;
          }

          //If we should _not_ ignore passed blocking products, we count them as blocking regardless of their validity time.
          //Meaning we keep ALL products for the blocking check.
          return true;
        })
        .map((product) => product.productId);

      const necessaryProductIds = new Set(
        necessaryProducts.filter(productHasProductData).map((product) => parseInt(product.productData.glkId)),
      );

      const blockingProductIds = new Set(
        blockingProducts.filter(productHasProductData).map((product) => parseInt(product.productData.glkId)),
      );

      const necessaryProductCount = productIdsUsedForNecessaryChecks.filter((productId) =>
        necessaryProductIds.has(productId),
      ).length;

      const blockingProductCount = productIdsUsedForBlockingChecks.filter((productId) =>
        blockingProductIds.has(productId),
      ).length;

      const hasNecessaryProductsOnAccount = necessaryProductCount > 0;

      if (!hasNecessaryProductsOnAccount) {
        return "LOGGED_IN_NOT_NECESSARY_PRODUCTS" as const;
      }

      let isBlockedByBlockingProducts = false;
      if (lockNecessaryProductsRatio === undefined) {
        // If ratio is undefined, any amount of blocking products will block access
        isBlockedByBlockingProducts = blockingProductCount > 0;
      } else {
        // If ratio is defined, check if blocking products has reached the allowed amount.
        // Calculate allowance: number of necessary products owned * ratio
        const allowedBlockingProducts = necessaryProductCount * lockNecessaryProductsRatio;
        isBlockedByBlockingProducts = blockingProductCount >= allowedBlockingProducts;
      }

      if (isBlockedByBlockingProducts) {
        return "LOGGED_IN_BLOCKING_PRODUCT" as const;
      }

      return "LOGGED_IN_NECESSARY_PRODUCTS" as const;
    }

    //Should never happen, but just to be safe
    return "ERROR" as const;
  }, [auth, necessaryProducts, blockingProducts, lockNecessaryProductsRatio, ignorePassedBlockingProducts]);

  useEffect(() => {
    if (lockState === "LOGGED_IN_NECESSARY_PRODUCTS") {
      setHasPassed(true);
    }
  }, [lockState, setHasPassed]);

  const onClickLoginLink = useOnPreNavigate(() => LocationHelper.setPostMyParksLogin(window.location.pathname));

  return (
    <div>
      <PageLockModal>
        <div className={multipleClassNames(styles.content, styles.biggerContent)}>
          {lockState === "LOADING" && <LoadingBlock className={styles.loader} />}

          {lockState === "NOT_LOGGED_IN" && (
            <>
              {lockMyPageMessageNotLoggedIn && <TextBlock {...lockMyPageMessageNotLoggedIn} size="m" />}
              <Link internalLink={routes.LOGIN.getSlug(LanguageHelper.getCurrentLocale())} onClick={onClickLoginLink}>
                <PrimaryButton label={t("login")} isFullWidth />
              </Link>
            </>
          )}
          {lockState === "LOGGED_IN_NECESSARY_PRODUCTS" && <p>{t("myPageLockSuccess")}</p>}
          {lockState === "LOGGED_IN_BLOCKING_PRODUCT" && (
            <>
              {lockMyPageMessageBlockingProducts && <TextBlock {...lockMyPageMessageBlockingProducts} size="m" />}
              {!lockMyPageMessageBlockingProducts && <p>{t("myPageLockBlockingProducts")}</p>}
            </>
          )}
          {lockState === "LOGGED_IN_NOT_NECESSARY_PRODUCTS" && (
            <>
              {lockMyPageMessageNotNecessaryProducts && (
                <TextBlock {...lockMyPageMessageNotNecessaryProducts} size="m" />
              )}
              {!lockMyPageMessageNotNecessaryProducts && <p>{t("myPageLockNotEnoughProducts")}</p>}
            </>
          )}
          {lockState === "ERROR" && <p>{t("somethingWentWrong")}</p>}
          <GhostButtonLink
            label={t("backToLandingPage")}
            url={homeRoute}
            isFullWidth
            className={styles.myPageLockHomeButton}
          />
        </div>
      </PageLockModal>
      <Component isLocked={true} {...props} />
    </div>
  );
};

const MyPageLockWithAuth = AuthAware(MyPageLock);

/**It is always asumed that the wall time entered in Contentful e.g "2024-08-01T12:00" is in Stockholm time */
const getUTCTimeFromDateTimeLock = (dateTimeLock?: string) => {
  return DateHelper.parseWallDateTimeToUTCDateTime(dateTimeLock, "Europe/Stockholm");
};

const getDateTimeLockParagraph = (t: Translation, dateTimeLockAsUTC: string) => {
  return t("dateTimeLockMessageParagraph", [
    `${DateHelper.toStringMMDDWeekday(dateTimeLockAsUTC)} ${DateHelper.toStringTimeHHMM(dateTimeLockAsUTC)}`,
  ]);
};

type DateTimeNotYetPassedLockProps<P> = {
  dateTimeLockAsUTC: string;
  Component: React.ComponentType<{ isLocked: boolean } & P>;
  props: P;
};
const DateTimeNotYetPassedLock = <P,>({ dateTimeLockAsUTC, Component, props }: DateTimeNotYetPassedLockProps<P>) => {
  const { t } = useTranslation();
  return (
    <div>
      <PageLockModal>
        <div className={styles.content}>
          <p className="bold">{t("dateTimeLockMessageHeading")}</p>
          <p className={styles.error}>{getDateTimeLockParagraph(t, dateTimeLockAsUTC)}</p>
        </div>
      </PageLockModal>
      <Component isLocked={true} {...props} />
    </div>
  );
};

const LockWithValue = ({
  props,
  hasPassed,
  setHasPassed,
  dateTimeLock,
  Component,
}: {
  props: LockedPageProps;
  hasPassed: boolean;
  setHasPassed: (passed: boolean) => void;
  dateTimeLock: { hasPassed: true } | { hasPassed: false; dateTimeLockAsUTC: string };
  Component: any;
}) => {
  const { t } = useTranslation();
  if (isCodeProps(props)) {
    return (
      <CodeLock
        code={props.lockValue}
        lockInputLabel={props.lockInputLabel}
        lockInputPlaceholder={props.lockInputPlaceholder}
        lockErrorMsg={props.lockErrorMsg}
        hasPassed={hasPassed}
        cacheCode={props.cacheCode}
        setHasPassed={setHasPassed}
        setIsViewportScrollable={props.setIsViewportScrollable}
        isDisabled={!dateTimeLock.hasPassed}
        // tsc complains that dateTimeLock in the second part of the ternary can also be the {hasPassed: true} part and hence dateTimeLockAsUTC might not exist.
        // That is not true since the ternary *should* narrow the type down to be {hasPassed: false; dateTimeLockAsUTC: string}.
        // There seems to be some discrepancy between using different typescript versions (the one in VS code vs tsc) and I have no idea why. So for now I'll just ignore the error.
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        bottomText={dateTimeLock.hasPassed ? undefined : getDateTimeLockParagraph(t, dateTimeLock.dateTimeLockAsUTC)}
        Component={Component}
        props={props}
      />
    );
  }

  if (isReferrerProps(props)) {
    return (
      <ReferrerLock
        validReferrer={props.lockValue}
        lockErrorMsg={props.lockErrorMsg}
        setHasPassed={setHasPassed}
        setIsViewportScrollable={props.setIsViewportScrollable}
        Component={Component}
        props={props}
      />
    );
  }

  if (isLocationParametersProps(props)) {
    return (
      <LocationParametersLock
        locationParameters={props.locationSearch}
        validPromoCode={props.lockValue}
        lockErrorMsg={props.lockErrorMsg}
        setHasPassed={setHasPassed}
        setIsViewportScrollable={props.setIsViewportScrollable}
        Component={Component}
        props={props}
      />
    );
  }

  if (isMyPageProps(props)) {
    return (
      <MyPageLockWithAuth
        necessaryProducts={props.lockNecessaryProducts}
        blockingProducts={props.lockBlockingProducts}
        ignorePassedBlockingProducts={props.ignorePassedBlockingProducts ?? false}
        lockMyPageMessageNotNecessaryProducts={props.lockMyPageMessageNotNecessaryProducts}
        lockMyPageMessageBlockingProducts={props.lockMyPageMessageBlockingProducts}
        lockNecessaryProductsRatio={props.lockNecessaryProductsRatio}
        lockMyPageMessageNotLoggedIn={props.lockMyPageMessageNotLoggedIn}
        setHasPassed={setHasPassed}
        Component={Component}
        props={props}
      />
    );
  }
  //Fallback just to be safe
  return <Component isLocked={false} {...props} />;
};

type CommonProps = {
  lockValue: string;
  lockErrorMsg: string;
  setIsViewportScrollable: (passed: boolean) => void;
  dateTimeLock?: string;
};

type CodeProps = {
  lockType: "Code";
  lockInputLabel?: string;
  lockInputPlaceholder?: string;
  cacheCode?: boolean;
} & CommonProps;

type ReferrerProps = {
  lockType: "Referrer";
} & CommonProps;

type LocationParametersProps = {
  lockType: "Location Parameters";
  locationSearch: string;
} & CommonProps;

type MyPageProps = {
  lockType: "MyPage";
  /** If any of these products exist on the account - they will be let through */
  lockNecessaryProducts: Array<ProductBlockFragment>;
  /** If any of these products exist on the account - they will however NOT be let through */
  lockBlockingProducts: Array<ProductBlockFragment>;
  /** If set to `true`, any product that has passed its validity will not be taken into consideration as a blocking product.
   * `false` means that _all_ products, regardless of their validity (how old they are), will be taken into consideration.
   *
   * Defaults to `false`.
   */
  ignorePassedBlockingProducts?: boolean;
  /**The number of blocking products that is allowed per necessesary product
   * If the ratio=6 and the guest has 2 lockNecessaryProducts in their account,
   * it means they are allowed to own 12 lockBlockingProducts before it is blocked.
   * `undefined` means that as soon as they have ANY amount of lockBlockingProducts, they are blocked (same as before) */
  lockNecessaryProductsRatio?: number;
  lockMyPageMessageNotNecessaryProducts?: TextBlockProps;
  lockMyPageMessageBlockingProducts?: TextBlockProps;
  lockMyPageMessageNotLoggedIn?: TextBlockProps;
} & CommonProps;

type DateTimeProps = {
  lockType?: undefined;
  dateTimeLock?: string;
};

export type LockedPageProps = CodeProps | ReferrerProps | LocationParametersProps | MyPageProps | DateTimeProps;

const isCodeProps = (props: LockedPageProps): props is CodeProps => props.lockType === "Code";

const isReferrerProps = (props: LockedPageProps): props is ReferrerProps => props.lockType === "Referrer";

const isLocationParametersProps = (props: LockedPageProps): props is LocationParametersProps =>
  props.lockType === "Location Parameters";

const isMyPageProps = (props: LockedPageProps): props is MyPageProps => props.lockType === "MyPage";

export const pageLock = <P,>(Component: any) =>
  function PageLockWrapper(props: LockedPageProps & P) {
    const [hasPassed, setHasPassed] = useState(false);
    const dateTimeLockAsUTC = getUTCTimeFromDateTimeLock(props.dateTimeLock);
    const hasDateTimePassed = dateTimeLockAsUTC ? DateHelper.hasDatePassed(dateTimeLockAsUTC) : true;

    const hasLockProps =
      isCodeProps(props) || isReferrerProps(props) || isLocationParametersProps(props) || isMyPageProps(props);
    const hasDateTimeProps = !!dateTimeLockAsUTC;

    if (hasLockProps && !hasPassed) {
      return (
        <LockWithValue
          props={props}
          hasPassed={hasPassed}
          setHasPassed={setHasPassed}
          dateTimeLock={
            !hasDateTimePassed && dateTimeLockAsUTC ? { hasPassed: false, dateTimeLockAsUTC } : { hasPassed: true }
          }
          Component={Component}
        />
      );
    }

    if (hasDateTimeProps && !hasDateTimePassed) {
      return <DateTimeNotYetPassedLock dateTimeLockAsUTC={dateTimeLockAsUTC} Component={Component} props={props} />;
    }

    return <Component isLocked={false} {...props} />;
  };
